_name_re = re.compile(r'"name"\s*:\s*"([^"\\]{1,128})"')

def salvage_name(s):
    "The top-level tool name from a call that was cut off, or None."
    depth, i, n = 0, 0, len(s or '')
    while i < n:
        c = s[i]
        if c == '"':
            if depth == 1 and (m := _name_re.match(s, i)): return m.group(1)
            _, i, _ = _loose_str(s, i, ',}]:')
            continue
        if c in '{[': depth += 1
        elif c in '}]': depth -= 1
        i += 1
    return None

