def mk_tc(name, args=None):
    "A tool call dict in the OpenAI shape, with a fresh `call_` id."
    return {'id': f'call_{uuid.uuid4().hex[:8]}', 'type': 'function',
            'function': {'name': name, 'arguments': args or {}}}

# %% ../nbs/01_tags.ipynb #e263321a
TAG_ARG_KEYS = ('arguments', 'input', 'parameters', 'args')
_TC_KEYS = ('name', 'id', 'type')

def tag_args(d):
    "The arguments of a parsed call body, under any of `TAG_ARG_KEYS`, or None when they cannot be read."
    keys = [k for k in TAG_ARG_KEYS if d.get(k) is not None]
    if not keys: return {k: v for k, v in d.items() if k not in _TC_KEYS}
    for v in (d[k] for k in keys):
        if isinstance(v, str): v, ok = loose_json(v); v = v if ok else None   # a cut string gives no partial arguments
        if isinstance(v, dict): return v
    return None

_stray_re = re.compile(r'(?:\s*<[^<>{}]*>)+\s*')

def mk_tag_tc(s):
    "A tool call dict from the body of a `<tool_call>` block, marked `unread` when its arguments were lost, or None."
    if (m := _stray_re.match(s or '')): s = s[m.end():]      # empty stray tags before the object are not part of it
    d, ok = loose_json(s)
    if d is not None and d.get('name'):
        # a cut object keeps only completed values. An `arguments` that is present is whole.
        args = tag_args(d) if ok or any(k in d for k in TAG_ARG_KEYS) else None
        return mk_tc(d['name'], args) if args is not None else {**mk_tc(d['name']), 'unread': True}
    if (name := salvage_name(s or '')): return {**mk_tc(name), 'unread': True}
    return None

# %% ../nbs/01_tags.ipynb #d6731f91
#: `<function=name>` (Qwen) or `<invoke name="name">` (Claude's own dialect)
_fn_re   = re.compile(r'<(?:function\s*=\s*|invoke\s+name\s*=\s*")([A-Za-z_][\w.\-]*)"?\s*>', re.I)
_fnend_re = re.compile(r'</(?:function|invoke)\s*>', re.I)
#: only a closed parameter is complete. A call with no closing tag keeps its name and is marked `unread`.
_par_re  = re.compile(r'<parameter(?:\s*=\s*|\s+name\s*=\s*")([A-Za-z_][\w.\-]*)"?\s*>(.*?)</parameter\s*>', re.I | re.S)
_num_re  = re.compile(r'-?\d+(?:\.\d+)?$')

def _unframe(v):
    "Drop the one framing newline the template puts on each side of a value, and nothing else."
    if v.startswith('\n'): v = v[1:]
    if v.endswith('\n'): v = v[:-1]
    return v

def _spelled(v):
    "A parameter value as the JSON it spells, else as the raw string it is."
    t = v.strip()
    if t[:1] in '{[' or t in ('true', 'false', 'null') or _num_re.match(t):
        try: return json.loads(t)
        except json.JSONDecodeError: pass
    return v

def parse_fn_tags(text):
    "Tool calls written in the `<function=name>` or `<invoke name=...>` XML form."
    out = []
    for m in _fn_re.finditer(text or ''):
        body = text[m.end():]
        if (n := _fn_re.search(body)): body = body[:n.start()]   # a call ends where the next one opens
        if not (e := _fnend_re.search(body)): out.append({**mk_tc(m.group(1)), 'unread': True}); continue
        body = body[:e.start()]
        args = {k: _spelled(_unframe(v)) for k, v in _par_re.findall(body)}
        if not args and (d := loose_json(body)[0]): args = d
        out.append(mk_tc(m.group(1), args))
    return out

# %% ../nbs/01_tags.ipynb #9482f0de
_res_tags = ('tool_result', 'tool_results', 'function_result', 'function_results',
             'tool_function_result', 'tool_function_results',
             'tool_function_call', 'tool_function_calls',
             'function_call', 'function_calls', 'tool_use')
_toolres_re = re.compile('|'.join(rf'</?{t}>>?' for t in _res_tags) + r'|</?tool_call>', re.I)
_toolcall_re = re.compile(r'<tool_call>\s*(.*?)\s*</tool_call>', re.DOTALL)
_fnblk_re = re.compile(r'<(?:function\s*=|invoke\s+name\s*=).*?(?:</(?:function|invoke)\s*>|$)', re.I | re.S)
_fence_re = re.compile(r'^```(?:json)?\s*|\s*```$')

def lone_tag_tc(text, names=None):
    "A tool call from a reply that is nothing but one untagged call object, or None."
    s = _fence_re.sub('', (text or '').strip()).strip()
    if not (s.startswith('{') and s.endswith('}')): return None
    d, ok = loose_json(s)
    if not ok or not isinstance(d, dict) or not d.get('name'): return None
    if not any(k in d for k in TAG_ARG_KEYS): return None
    # with `names`, an untagged object must name a known tool. Otherwise the model is talking about JSON.
    if names is not None and d['name'] not in set(names): return None
    return mk_tc(d['name'], tag_args(d))

# %% ../nbs/01_tags.ipynb #a097ff21
_strayp_re = re.compile(r'<parameter\b[^>]*>(?:.*?</parameter\s*>)?|</parameter\s*>', re.I | re.S)

_open_re = re.compile('<tool_' + 'call>')
_lead_re = re.compile(r'\s*(?:<[^<>{}]*>\s*)*')
_close_re = re.compile(r'\s*</tool_' + 'call>')

def tool_blocks(text):
    "The `(start, end, body)` of each closed call block in `text`. A JSON body is read whole, so a closing tag quoted inside a string does not end the block."
    out, i, dec = [], 0, json.JSONDecoder()
    while (o := _open_re.search(text, i)):
        a, j = o.start(), o.end(); k = _lead_re.match(text, j).end()
        if text[k:k+1] == '{':
            try:
                _, e = dec.raw_decode(text, k)
                if (c := _close_re.match(text, e)): out.append((a, c.end(), text[j:e].strip())); i = c.end(); continue
            except json.JSONDecodeError: pass
        if not (m := _toolcall_re.match(text, a)): break      # no closing tag follows: the opener was left open
        out.append((a, m.end(), m.group(1))); i = m.end()
    return out

def _block_calls(body):
    "The calls in one call-block body. A body that opens a JSON object is a JSON call: its strings are never scanned for the XML form."
    start = _stray_re.match(body)
    head = body[start.end():] if start else body
    if head.lstrip().startswith('{'):
        return [tc] if (tc := mk_tag_tc(body)) else []
    if (tcs := parse_fn_tags(body)): return tcs
    return [tc] if (tc := mk_tag_tc(body)) else []

def parse_tool_tags_ex(text, names=None):
    "Parse tool calls out of `text`, returning `(clean_text, calls, failed)`, where `failed` means a block could not be read."
    t = text or ''
    blocks, rest, p, positioned = tool_blocks(t), '', 0, []
    for a, e, _ in blocks:
        segment = t[p:a]
        positioned += [(p + m.start(), tc) for m, tc in zip(_fn_re.finditer(segment), parse_fn_tags(segment))]
        rest += segment; p = e
    segment = t[p:]
    if (opener := _open_re.search(segment)): segment = segment[:opener.start()]
    positioned += [(p + m.start(), tc) for m, tc in zip(_fn_re.finditer(segment), parse_fn_tags(segment))]
    rest += t[p:]
    tail = ''
    if (k := rest.rfind('<tool_call>')) >= 0:   # an opener the model never closed, for example at the token cap
        tail, rest = rest[k + len('<tool_call>'):], rest[:k]
    failed = False
    for a, _, b in blocks:
        if (cs := _block_calls(b)): positioned += [(a, tc) for tc in cs]
        else: failed = True             # an unreadable block sets `failed`
    if k >= 0:
        if (cs := _block_calls(tail)): positioned += [(len(t) - len(tail), tc) for tc in cs]
        else: failed = True
    tcs = [tc for _, tc in sorted(positioned, key=lambda item: item[0])]
    if not tcs and not failed and (tc := lone_tag_tc(t, names)): return '', [tc], False
    clean = _fnblk_re.sub('', _toolres_re.sub('', rest))
    if _fn_re.search(t): clean = _strayp_re.sub('', clean)   # stray parameters that a damaged reply left between its calls
    return clean.strip('\n'), tcs, failed

def parse_tool_tags(text, names=None):
    "Parse tool calls out of `text`, returning `(clean_text, calls)`."
    return parse_tool_tags_ex(text, names)[:2]

# %% ../nbs/01_tags.ipynb #530417a6
def tag_call_shape(text, names=None):
    "True when `text` still looks like a tool call, optionally only for tools in `names`."
    t = text or ''
    if '<tool_call' in t: return True
    if not any(f'"{k}"' in t for k in TAG_ARG_KEYS): return False
    pat = '|'.join(re.escape(str(n)) for n in (names or []) if n) if names is not None else r'[A-Za-z_]\w*'
    return bool(pat) and bool(re.search(rf'"name"\s*:\s*"(?:{pat})"', t))

# %% ../nbs/01_tags.ipynb #150e47be
TAG_TOOLS_SP = """

# Tools

You can call the functions below. Their signatures are given as JSON schemas inside \
<tools></tools>:

<tools>
{tools}
</tools>

To call one, emit a JSON object with the function's name and its arguments inside \
<tool_call></tool_call>:

<tool_call>
{{"name": "the_function_name", "arguments": {{"first": "value"}}}}
</tool_call>

Calls that do not depend on each other's results -- reading several files, running several \
searches -- go together in one message, each in its own <tool_call> block, one after another. \
A call that needs an earlier result waits for it.

After the last </tool_call>, end your reply and wait. Nothing may follow it in the same message: \
not a comment, and not a guess at what a result will be.

Do not describe a call in prose as well as emitting it, and never invent a result -- the real \
ones come back in the next message, each under a "## Tool result (name)" heading. That heading \
is the only form a result ever takes: do not write result markup of your own, do not wrap a \
result in tags, and do not copy a result back into your reply. Say what you concluded from it, \
not what it said."""

def tag_tools_sp(toolspecs, sp='', template=TAG_TOOLS_SP):
    "Append the tool schemas and the `<tool_call>` instructions to the system prompt `sp`."
    if not toolspecs: return sp
    block = '\n'.join(json.dumps(t, ensure_ascii=False) for t in toolspecs)
    return (sp or '') + template.format(tools=block)

